CREATE OR REPLACE FUNCTION public.rpc_game_action(pw text, p_game_id integer, p_player text, p_action text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_game games%ROWTYPE;
    v_player_side CHAR(1);
    v_opp_is_bot BOOLEAN := FALSE;
BEGIN
    PERFORM check_pw(pw);
    SELECT * INTO v_game FROM games WHERE id = p_game_id FOR UPDATE;

    IF v_game.status <> 'active' THEN
        RAISE EXCEPTION 'Partie ist nicht mehr aktiv.';
    END IF;

    IF v_game.white_player = p_player THEN
        v_player_side := 'w';
        SELECT is_bot INTO v_opp_is_bot FROM players WHERE name = v_game.black_player;
    ELSIF v_game.black_player = p_player THEN
        v_player_side := 'b';
        SELECT is_bot INTO v_opp_is_bot FROM players WHERE name = v_game.white_player;
    ELSE
        RAISE EXCEPTION 'Du bist nicht Teil dieser Partie.';
    END IF;

    IF p_action = 'abort' THEN
        IF v_game.move_count > 1 THEN
            RAISE EXCEPTION 'Nach dem ersten Zug kann nur noch aufgegeben werden.';
        END IF;
        UPDATE games SET status = 'aborted', result_reason = 'Vorzeitig beendet', updated_at = NOW()
        WHERE id = p_game_id RETURNING * INTO v_game;

    ELSIF p_action = 'resign' THEN
        IF v_player_side = 'w' THEN
            UPDATE games SET status = 'black_won', result_reason = 'Aufgabe durch Weiß', updated_at = NOW()
            WHERE id = p_game_id RETURNING * INTO v_game;
            PERFORM update_elo(v_game.white_player, v_game.black_player, 0.0);
        ELSE
            UPDATE games SET status = 'white_won', result_reason = 'Aufgabe durch Schwarz', updated_at = NOW()
            WHERE id = p_game_id RETURNING * INTO v_game;
            PERFORM update_elo(v_game.white_player, v_game.black_player, 1.0);
        END IF;

    ELSIF p_action = 'offer_draw' THEN
        IF v_opp_is_bot THEN
            RAISE EXCEPTION 'Ein Computer-Bot nimmt leider keine Remis-Angebote an!';
        END IF;
        UPDATE games SET draw_offered_by = v_player_side, updated_at = NOW()
        WHERE id = p_game_id RETURNING * INTO v_game;

    ELSIF p_action = 'accept_draw' THEN
        IF v_game.draw_offered_by IS NOT NULL AND v_game.draw_offered_by <> v_player_side THEN
            UPDATE games SET status = 'draw', result_reason = 'Remis vereinbart', updated_at = NOW()
            WHERE id = p_game_id RETURNING * INTO v_game;
            PERFORM update_elo(v_game.white_player, v_game.black_player, 0.5);
        ELSE
            RAISE EXCEPTION 'Kein offenes Remis-Angebot des Gegners vorhanden.';
        END IF;
    END IF;

    RETURN row_to_json(v_game);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_make_move(pw text, p_game_id integer, p_player text, p_new_fen text, p_move_uci text, p_new_status text, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_game games%ROWTYPE;
    v_today DATE := (NOW() AT TIME ZONE 'Europe/Berlin')::DATE;
    v_is_white BOOLEAN;
    v_is_bot_player BOOLEAN;
BEGIN
    PERFORM check_pw(pw);
    SELECT * INTO v_game FROM games WHERE id = p_game_id FOR UPDATE;

    IF v_game.status <> 'active' THEN
        RAISE EXCEPTION 'Diese Partie ist bereits beendet.';
    END IF;

    v_is_white := (v_game.turn = 'w' AND v_game.white_player = p_player);
    IF NOT v_is_white AND NOT (v_game.turn = 'b' AND v_game.black_player = p_player) THEN
        RAISE EXCEPTION 'Du bist in dieser Partie gerade nicht am Zug!';
    END IF;

    SELECT is_bot INTO v_is_bot_player FROM players WHERE name = p_player;

    -- 1-Zug-pro-Tag-Prüfung (Reset um 00:00 Uhr deutscher Zeit; Bots dürfen sofort antworten)
    IF NOT v_is_bot_player THEN
        IF v_is_white AND v_game.white_last_move_date = v_today THEN
            RAISE EXCEPTION 'Du hast heute in dieser Partie bereits gezogen! Nächster Zug ab 00:00 Uhr.';
        END IF;
        IF NOT v_is_white AND v_game.black_last_move_date = v_today THEN
            RAISE EXCEPTION 'Du hast heute in dieser Partie bereits gezogen! Nächster Zug ab 00:00 Uhr.';
        END IF;
    END IF;

    UPDATE games SET
        fen = p_new_fen,
        turn = CASE WHEN v_game.turn = 'w' THEN 'b' ELSE 'w' END,
        status = p_new_status,
        result_reason = p_reason,
        white_last_move_date = CASE WHEN v_is_white AND NOT v_is_bot_player THEN v_today ELSE white_last_move_date END,
        black_last_move_date = CASE WHEN NOT v_is_white AND NOT v_is_bot_player THEN v_today ELSE black_last_move_date END,
        last_move_uci = p_move_uci,
        moves_history = CASE WHEN moves_history = '' THEN p_move_uci ELSE moves_history || ' ' || p_move_uci END,
        draw_offered_by = NULL,
        move_count = move_count + 1,
        updated_at = NOW()
    WHERE id = p_game_id
    RETURNING * INTO v_game;

    -- Falls die Partie durch diesen Zug endet (Matt / Patt / 50-Züge), Elo sofort berechnen
    IF p_new_status = 'white_won' THEN
        PERFORM update_elo(v_game.white_player, v_game.black_player, 1.0);
    ELSIF p_new_status = 'black_won' THEN
        PERFORM update_elo(v_game.white_player, v_game.black_player, 0.0);
    ELSIF p_new_status = 'draw' THEN
        PERFORM update_elo(v_game.white_player, v_game.black_player, 0.5);
    END IF;

    RETURN row_to_json(v_game);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_start_game(pw text, p_creator text, p_opponent text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_white TEXT;
    v_black TEXT;
    v_game games%ROWTYPE;
BEGIN
    PERFORM check_pw(pw);

    IF random() < 0.5 THEN
        v_white := p_creator;
        v_black := p_opponent;
    ELSE
        v_white := p_opponent;
        v_black := p_creator;
    END IF;

    INSERT INTO games (white_player, black_player)
    VALUES (v_white, v_black)
    RETURNING * INTO v_game;

    RETURN row_to_json(v_game);
END;
$function$

CREATE OR REPLACE FUNCTION public.rpc_sync_state(pw text, p_name text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_today DATE;
    v_players JSON;
    v_games JSON;
BEGIN
    PERFORM check_pw(pw);
    v_today := (NOW() AT TIME ZONE 'Europe/Berlin')::DATE;

    -- Spieler automatisch mit Start-Elo 500 anlegen, falls neu (Name nicht leer)
    IF p_name IS NOT NULL AND LENGTH(TRIM(p_name)) > 0 THEN
        INSERT INTO players (name, elo, is_bot)
        VALUES (TRIM(p_name), 500, FALSE)
        ON CONFLICT (name) DO NOTHING;
    END IF;

    SELECT json_agg(t) INTO v_players FROM (
        SELECT name, elo, wins, draws, losses, is_bot, bot_level
        FROM players ORDER BY elo DESC, wins DESC, name ASC
    ) t;

    SELECT COALESCE(json_agg(g), '[]'::json) INTO v_games FROM (
        SELECT * FROM games
        WHERE status <> 'aborted'
        ORDER BY updated_at DESC LIMIT 60
    ) g;

    RETURN json_build_object(
        'today', v_today,
        'players', v_players,
        'games', v_games
    );
END;
$function$
